<!--vbase-->
<template>
  <div
    v-if="showDuplicateDocBanner"
    class="q-dialog fullscreen no-pointer-events q-dialog--modal banner-parent"
  >
    <div
      class="q-dialog__backdrop fixed-full"
      aria-hidden="true"
      style="--q-transition-duration: 300ms"
    ></div>
    <div class="warring-banner row q-dialog__inner all-pointer-events">
      <span class="left-side">
        <q-btn class="reload-doc text-weight-bold" to="/dashboard">
          {{ $t('dashboard') }}
        </q-btn>
        <q-btn
          v-if="doc_status !== 'archived'"
          class="reload-doc text-weight-bold q-ml-sm"
          @click="addDocToArchive"
        >
          {{ $t('archive') }}
        </q-btn>
      </span>

      <span class="message">
        {{ $t('duplicate_document_has_been_detected') }}
      </span>

      <span class="right-side">
        <q-btn
          class="force-unlock text-weight-bold"
          @click="showDuplicateInvoices = true"
        >
          {{ $t('view_duplicate') }}
        </q-btn>
        <q-btn class="reload-doc text-weight-bold q-ml-sm" @click="removeBaner()">
          {{ $t('proceed_anyway') }}
        </q-btn>
      </span>
    </div>
  </div>

  <q-dialog v-model="showDuplicateInvoices" full-width>
    <q-card>
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">{{ $t('duplicate_detection') }}</span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <DuplicateDlalog
        :document_ids="duplicateDocumentIds"
        :display_data="duplicateInvoiceList"
      />
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { documentListApiService } from 'src/services';
import { documentDetailApiService } from 'src/services';
import DuplicateDlalog from 'src/components/DuplicateInvoices/DuplicateDlalog.vue';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  name: 'duplicate-invoice-msg',
  props: {
    doc_id: {
      type: String,
      default: '',
    },
    doc_type: {
      type: String,
      default: '',
    },
    doc_status: {
      type: String,
      default: '',
    },
  },
  emits: ['setInvoiceDuplicateStatus'],
  components: { DuplicateDlalog },
  data() {
    return {
      duplicateDocumentIds: ref(''),
      showDuplicateInvoices: ref(false),
      duplicateInvoiceList: ref([] as any),
      docId: this.$route.params.id as string,
      showDuplicateDocBanner: ref(false),
    };
  },
  mounted: function () {
    this.init();
    window.addEventListener('keydown', this.handleEsc);
  },
  beforeUnmount() {
    window.removeEventListener('keydown', this.handleEsc);
  },
  methods: {
    init() {
      this.getDocumnetDuplicates();
    },
    async getDocumnetDuplicates() {
      if (!this.doc_id || !this.doc_type) {
        return;
      }
      try {
        const queryParams =
          'legacy_format=false&doc_id=' +
          this.doc_id +
          '&doc_type=' +
          this.doc_type;
        const response =
          await documentListApiService.getDuplicateInvoices(queryParams);

        if (!response.success) {
          this.removeBaner();
          throw response;
        }

        if (
          response.duplicate_documents.length == 0 &&
          response.supplier_invoice_duplicates.length == 0
        ) {
          this.removeBaner();
          return;
        }

        this.showDuplicateDocBanner = true;
        if (
          response.duplicate_documents &&
          response.duplicate_documents.length > 0
        ) {
          this.duplicateDocumentIds = response.duplicate_documents.join(',');
        }

        if (
          response.supplier_invoice_duplicates &&
          response.supplier_invoice_duplicates.length > 0
        ) {
          this.duplicateInvoiceList = response.supplier_invoice_duplicates;
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    removeBaner() {
      this.$emit('setInvoiceDuplicateStatus', false);
    },
    handleEsc(event: any) {
      if (event.key === 'Escape') {
        this.removeBaner();
      }
    },
    async addDocToArchive() {
      try {
        const response = await documentDetailApiService.set_document_status(
          this.docId,
          {
            status: 'archived',
          },
        );

        if (response.success === false) {
          throw { message: response.message };
        }
        this.$router.push('/dashboard');
        notify.success(this.$t('status_updated_successfully'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
  },
  setup() {
    return {};
  },
});
</script>

